public int findLargestSubstring(List<String> strings) {
    int largestLength = 0;
    String largestString = null;

    // Iterate over the list of strings
    for (String s : strings) {
        // Check if the current string is a substring of any other string in the list
        for (String t : strings) {
            if (t.contains(s) || s.contains(t)) {
                // If the current string is a substring of another string, check if it is larger than the current largest string
                if (s.length() > largestLength) {
                    largestLength = s.length();
                    largestString = s;
                }
                // Break out of the loop if the current string is found to be a substring of another string
                break;
            }
        }
    }

    // Return the length of the largest string
    return largestLength;
}

