public int findLargestSubstring(List<String> strings) {
    if (strings.isEmpty()) {
        throw new IllegalArgumentException("List must not be empty");
    }

    StringBuilder sb = new StringBuilder();
    for (String str : strings) {
        sb.append(str);
    }

    String allStringsJoined = sb.toString();
    String revString = new StringBuilder(allStringsJoined).reverse().toString();

    int largestLen = 0;
    for (String str : strings) {
        int len = Math.max(str.length(), revString.indexOf(str));
        if (len > largestLen) {
            largestLen = len;
        }
    }

    return largestLen;
}

