public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialization
    int[][] dist = new int[n][n]; // Distance matrix
    Queue<int[]> queue = new LinkedList<int[]>(); // Queue for BFS
    boolean[] visited = new boolean[n]; // Visited nodes

    // Initialize distance matrix and queue
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) dist[i][j] = 0;
            else dist[i][j] = Integer.MAX_VALUE;
        }
        queue.add(new int[]{i, 0}); // Start from node 0
    }

    // BFS
    while (!queue.isEmpty()) {
        int[] node = queue.poll();
        int src = node[0];
        int time = node[1];

        if (visited[src]) continue; // If already visited, skip
        visited[src] = true;

        for (int i = 0; i < edges[src].length; i++) {
            int dst = edges[src][i];
            if (dist[src][dst] > dist[src][0] + 1) { // If edge not visited, update distance
                dist[src][dst] = dist[src][0] + 1;
                queue.add(new int[]{dst, time + 1});
            }
        }
    }

    // Find minimum time to visit all nodes
    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) minTime += dist[0][i];
    }

    return minTime;
}

