public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int operations = 0;
    while (Arrays.stream(arr).distinct().count() > 1) {
        int x = Arrays.stream(arr).min().getAsInt();
        int y = Arrays.stream(arr).max().getAsInt();
        if (x == y) {
            break;
        }
        arr[x] -= 1;
        arr[y] += 1;
        operations++;
    }

    return operations;
}

