public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    // the value of the string is the sum of the positions of its characters in the alphabet (starting from 1)
    int [] alphabet = {1, 4, 7, 10, 13, 16, 19, 22, 25};
    // loop through the alphabet and find the character that has the smallest value
    for (int i = 0; i < n; i++) {
        int value = 0;
        for (int j = 0; j < alphabet.length; j++) {
            value = Math.min(value, Math.min(i * alphabet[j], k));
        }
        // store the character that has the smallest value
        sb.append((char) (value + 'A' - 1));
        // deduct the value of the character from the total value
        k -= value;
    }
    return sb.toString();
}

