public static int addDigits(int num) {
    // edge case: if num is less than or equal to 9, return num
    if (num <= 9) {
        return num;
    }

    // repeatedly add all digits of num until the result is a single digit
    while (num > 9) {
        // obtain the sum of all digits
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        // if the sum is less than or equal to 9, return the sum
        if (sum <= 9) {
            return sum;
        }
    }

    // if the result is greater than 9, recursively invoke the function on the result
    return addDigits(num);
}

