public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        String num = String.valueOf(i);
        int len = num.length();
        int mid = len / 2;
        String left = num.substring(0, mid);
        String right = num.substring(mid);
        if (left.equals(new StringBuilder(right).reverse().toString())) {
            result.add(num);
        }
    }
    return result;
}

