public static boolean isBoomerang(int[][] points) {
    // Check if the array of points is valid
    if (points == null || points.length < 3) {
        throw new IllegalArgumentException("At least three points must be provided");
    }

    // Calculate the area of the triangle formed by the three points
    double area = Math.abs(points[0][0] * points[1][1] + points[1][0] * points[2][1] + points[2][0] * points[0][1]
                - points[0][1] * points[1][0] - points[1][1] * points[2][0] - points[2][1] * points[0][0]) / 2;

    // If the area of the triangle is greater than zero, the points form a boomerang
    return area > 0;
}

