public static boolean isBoomerang(int[][] points) {
    // Check if the array of points has at least 3 elements
    if (points.length < 3) {
        throw new IllegalArgumentException("At least 3 points are required to form a boomerang.");
    }

    // Check if the points form a line
    boolean isALine = true;
    for (int i = 1; i < points.length; i++) {
        if (points[i][0] - points[i - 1][0] != points[i - 1][0] - points[i - 2][0] || points[i][1] - points[i - 1][1] != points[i - 1][1] - points[i - 2][1]) {
            isALine = false;
            break;
        }
    }

    // Check if the points form a circle
    boolean isACircle = true;
    for (int i = 0; i < points.length; i++) {
        double distance = Math.sqrt(Math.pow(points[i][0] - points[0][0], 2) + Math.pow(points[i][1] - points[0][1], 2));
        // If at least one point is not on the circle, return false
        if (distance < 0.001 || distance > 0.001) {
            isACircle = false;
            break;
        }
    }

    // Return true if the points form a boomerang
    return !isALine && isACircle;
}

